const fields = $input.item.json.fields || $input.item.json;
const recordId = $input.item.json.id || fields.id || '';
const title = fields.Title || 'this piece';
const instagramCaption = fields['Instagram Caption'] || '';
const facebookCaption = fields['Facebook  Caption'] || '';
const originalCaption = fields.Caption || '';
const baseContent = instagramCaption || originalCaption || title;

if (!baseContent || baseContent.trim() === '') {
  return { json: { skip: true, recordId, reason: 'No content to repurpose' } };
}

const prompt = `You are a content strategist for Dorothy Dean Designs, a faith-based luxury streetwear brand rooted in Black culture.\n\nBrand voice: grounded, affirming, calm but confident, culturally fluent. Never preachy.\n\nOriginal Instagram post:\nTitle: ${title}\nCaption: ${baseContent}\n\nRepurpose this content into 4 different formats. Return ONLY valid JSON with exactly these keys:\n{\n  "twitter_thread": "A 3-tweet thread. Each tweet separated by \\n---\\n. Under 280 chars each. Conversational, no hashtags needed.",\n  "linkedin_post": "Professional but warm LinkedIn post, 2-3 paragraphs. Speak to faith-driven professionals. Include 2-3 relevant hashtags at end.",\n  "blog_intro": "Opening 2 paragraphs for a blog post based on this content. Storytelling style, draws the reader in.",\n  "email_snippet": "Short email marketing snippet (2-3 sentences) suitable for a newsletter. First-person brand voice. No subject line needed.",\n  "pinterest_description": "Pinterest pin description, 100-150 words. Keyword-rich but natural. Include faith, style, and culture keywords."
}`;

return { json: { recordId, title, baseContent, prompt, skip: false } };

const resp = $input.item.json;
const text = resp.content && resp.content[0] ? resp.content[0].text : '';
let parsed;
try {
  const match = text.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : text);
} catch(e) {
  parsed = {
    twitter_thread: text,
    linkedin_post: '',
    blog_intro: '',
    email_snippet: '',
    pinterest_description: ''
  };
}
const prev = $('Build Repurpose Prompt').item.json;
return { json: {
  recordId: prev.recordId,
  twitterThread: parsed.twitter_thread || '',
  linkedinPost: parsed.linkedin_post || '',
  blogIntro: parsed.blog_intro || '',
  emailSnippet: parsed.email_snippet || '',
  pinterestDescription: parsed.pinterest_description || '',
  repurposedAt: new Date().toISOString()
} };
